function fresh(name,gender,origin,slot){let attrs={body:3,reflexes:3,tech:3,intelligence:3,cool:3};({Streetkid:'cool',Corpo:'intelligence',Nomad:'reflexes'})[origin]&&(attrs[({Streetkid:'cool',Corpo:'intelligence',Nomad:'reflexes'})[origin]]+=2);return {version:2,name,gender,origin,slot,level:1,xp:0,points:0,stats:attrs,health:100,energy:100,psy:0,cash:500,day:1,hour:20,weather:'Rain',district:'downtown',wanted:0,heat:0,inventory:[{id:'rust',qty:1},{id:'vest',qty:1},{id:'med',qty:3},{id:'battery',qty:2},{id:'scrap',qty:5}],weapon:'rust',armor:'vest',mods:{},cyber:{},ammo:12,reserve:48,ram:60,trace:0,trauma:0,psyResist:0,streetCred:0,cyberAccess:[],cyberUses:0,localScene:null,survival:false,hunger:100,thirst:100,vehicleFuel:{},vehicleDamage:{},cars:[],activeCar:null,upgrades:{},homes:[],businesses:[],reputation:Object.fromEntries(FACTIONS.map(x=>[x,0])),relationships:Object.fromEntries(NPCS.map(n=>[n.id,{affection:0,trust:0,dates:0,status:'Stranger',companion:false}])),missions:[],activeMission:null,completed:0,kills:0,defeats:0,questCounter:0,skillUnlocks:[],log:['Neural link established. Welcome to the Free City.'],feed:['📡 Welcome to LA-99. Stay sharp.'],lastIncome:1};}
const levelXP=l=>100*l*l, maxHp=()=>100+(state.level-1)*9+Math.max(0,state.stats.body-3)*12, maxEn=()=>100+(state.level-1)*3, armorValue=()=>((ARMOR.find(a=>a.id===state.armor)||ARMOR[0]).armor+(state.cyber.skin?5:0)), capacity=()=>40+state.stats.body*8, inventoryWeight=()=>state.inventory.reduce((n,i)=>n+(item(i.id)?.weight||0)*i.qty,0);
const item=id=>[...WEAPONS,...ARMOR,...CONSUME].find(x=>x.id===id),quantity=id=>state.inventory.find(i=>i.id===id)?.qty||0;
function gainItem(id,qty=1){const it=item(id);if(!it)return false;if(inventoryWeight()+it.weight*qty>capacity()){notify('🎒 Inventory overloaded. Sell or use items.');return false;}const e=state.inventory.find(i=>i.id===id);e?e.qty+=qty:state.inventory.push({id,qty});return true;}
function removeItem(id,qty=1){let e=state.inventory.find(i=>i.id===id);if(!e||e.qty<qty)return false;e.qty-=qty;state.inventory=state.inventory.filter(i=>i.qty>0);return true;}
function addFeed(msg){state.feed.unshift(msg);state.feed=state.feed.slice(0,16);state.log.unshift(`[Day ${state.day}, ${String(state.hour).padStart(2,'0')}:00] ${msg}`);state.log=state.log.slice(0,100);}
function notify(msg){let t=$('#toast');t.textContent=msg;t.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.add('hidden'),3200);if(settings.sound)beep();}
function beep(){try{audio??=new(window.AudioContext||window.webkitAudioContext)();let o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=650;g.gain.value=.018;o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.07);}catch{}}
function tick(hours=1){state.hour+=hours;while(state.hour>=24){state.hour-=24;state.day++;state.wanted=Math.max(0,state.wanted-1);state.ram=Math.min(60,state.ram+30);state.trace=Math.max(0,state.trace-35);state.psy=Math.max(0,state.psy-5);if(state.survival){state.hunger=Math.max(0,state.hunger-12);state.thirst=Math.max(0,state.thirst-18);}let inc=state.businesses.reduce((sum,id)=>sum+(BUSINESSES.find(b=>b.id===id)?.income||0),0);if(inc){state.cash+=inc;addFeed(`💼 Passive business earnings: ₡${fmt(inc)}.`);} }if(Math.random()<.14)state.weather=pick(['Clear','Rain','Fog','Storm','Smog']);}
function xpGain(n){state.xp+=n;let gains=0;while(state.xp>=levelXP(state.level)){state.xp-=levelXP(state.level);state.level++;state.points+=2;gains++;}if(gains){state.health=maxHp();state.energy=maxEn();addFeed(`🌟 Level ${state.level}! +${2*gains} attribute points.`);notify(`🌟 LEVEL UP: ${state.level}`);}}
function reputation(faction,delta){state.reputation[faction]=Math.max(-100,Math.min(100,(state.reputation[faction]||0)+delta));}
function persist(){if(!state)return;try{localStorage.setItem('nr2099-slot-'+state.slot,JSON.stringify(state));localStorage.setItem('nr2099-last',String(state.slot));$('#statusSave').textContent='✓ AUTOSAVED • SLOT '+(state.slot+1);}catch{notify('⚠ Local save failed. Storage may be full or disabled.');}}
function readSlot(slot){try{let s=JSON.parse(localStorage.getItem('nr2099-slot-'+slot));return validateSave(s)?s:null;}catch{return null;}}
function validateSave(s){return !!(s&&s.version===2&&typeof s.name==='string'&&s.name.length<80&&s.stats&&Array.isArray(s.inventory)&&Array.isArray(s.missions)&&Array.isArray(s.cars)&&Array.isArray(s.homes)&&Array.isArray(s.businesses)&&s.relationships&&s.reputation&&Number.isFinite(s.cash)&&s.cash>=0&&s.level>=1&&s.level<=999);}
let deathRestored=false;function saveRender(){if(state){if(!deathRestored&&!combat)persist();deathRestored=false;render();}}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').classList.remove('hidden');}function closeModal(){$('#modal').classList.add('hidden');}
function boot(){let i=0;let timer=setInterval(()=>{i=Math.min(100,i+R(7,19));$('#bootBar').style.width=i+'%';if(i>=100){clearInterval(timer);setTimeout(()=>{$('#boot').classList.add('hidden');showMenu();},250)}},90);}
function showMenu(){state=null;combat=null;$('#menu').classList.remove('hidden');$('#game').classList.add('hidden');}
function upgradeState(){const fallback={ammo:12,reserve:48,ram:60,trace:0,trauma:0,psyResist:0,streetCred:0,cyberAccess:[],cyberUses:0,localScene:null,survival:false,hunger:100,thirst:100,vehicleFuel:{},vehicleDamage:{}};for(const [k,v] of Object.entries(fallback))if(state[k]===undefined)state[k]=v;}
function startGame(data){state=data;upgradeState();activeSlot=state.slot;state.health=Math.min(state.health,maxHp());state.energy=Math.min(state.energy,maxEn());if(!state.missions.length)for(let i=0;i<4;i++)state.missions.push(generateMission());$('#menu').classList.add('hidden');$('#game').classList.remove('hidden');closeModal();view='map';addFeed(`◈ Welcome back, ${state.name}.`);saveRender();}
function characterModal(){modal(`<h2>✦ CREATE YOUR LEGEND</h2><p class="hint">New identity • New enemies • One city.</p><div class="field"><label>Mercenary name</label><input id="newName" maxlength="24" value="Vesper" autocomplete="off"></div><div class="field"><label>Identity</label><select id="newGender"><option>Female</option><option>Male</option><option>Nonbinary</option></select></div><div class="field"><label>Origin / Lifepath</label><select id="newOrigin"><option>Streetkid</option><option>Corpo</option><option>Nomad</option></select></div><div class="field"><label>Save slot</label><select id="newSlot">${[0,1,2].map(i=>`<option value="${i}">Slot ${i+1}${readSlot(i)?' • EXISTING (will overwrite)':' • Empty'}</option>`).join('')}</select></div><p class="hint">Streetkid: +2 Cool • Corpo: +2 Intelligence • Nomad: +2 Reflexes</p><button class="primary" data-action="create">🚀 ENTER LOS ANGELES</button>`);}
function slotModal(){modal(`<h2>▤ NEURAL SAVE ARCHIVE</h2><p class="hint">Three browser slots plus encrypted portable export files. Loading always starts at the title screen on refresh.</p><div class="stack">${[0,1,2].map(i=>{let s=readSlot(i);return `<div class="card"><div class="row between"><strong>SLOT ${i+1}</strong><span class="pill">${s?`LV ${s.level} • DAY ${s.day}`:'EMPTY'}</span></div><p>${s?`${esc(s.name)} • ${esc(s.origin)} • ₡${fmt(s.cash)}`:'No save created'}</p><div class="actions">${s?`<button data-action="load" data-slot="${i}">▶ LOAD</button><button data-action="export" data-slot="${i}">🔒 EXPORT</button><button class="danger" data-action="delete" data-slot="${i}">✕ DELETE</button>`:`<button data-action="new">✦ CREATE</button>`}</div></div>`}).join('')}</div>`);}
function continueGame(){let id=Number(localStorage.getItem('nr2099-last')||0);let s=readSlot(id)||[0,1,2].map(readSlot).find(Boolean);if(s)startGame(s);else slotModal();}
function navTo(id){if(combat&&id!=='combat'){notify('⚔️ Finish or flee the encounter first.');return;}view=id;render();}
function render(){if(!state)return;$('#playerName').textContent=state.name.toUpperCase();$('#playerSub').textContent=`${state.origin} • Level ${state.level}`;$('#hpNumber').textContent=`${Math.ceil(state.health)}/${maxHp()}`;$('#enNumber').textContent=`${Math.ceil(state.energy)}/${maxEn()}`;$('#psyNumber').textContent=`${Math.ceil(state.psy)}%`;$('#xpNumber').textContent=`${state.xp}/${levelXP(state.level)}`;for(const [id,n,d] of [['hp',state.health,maxHp()],['en',state.energy,maxEn()],['psy',state.psy,100],['xp',state.xp,levelXP(state.level)]])$('#'+id+'Meter').style.width=Math.min(100,100*n/d)+'%';$('#timeText').textContent=`${state.hour>=19||state.hour<6?'🌙':'☀️'} D${state.day} ${String(state.hour).padStart(2,'0')}:00`;$('#weatherText').textContent=({Rain:'🌧️',Storm:'⛈️',Fog:'🌫️',Smog:'☁️',Clear:'🌤️'}[state.weather]||'☀️')+' '+state.weather;$('#cashText').textContent='₡ '+fmt(state.cash);$('#wantedText').textContent='★'.repeat(Math.min(5,state.wanted))+'☆'.repeat(5-Math.min(5,state.wanted));$('#nav').innerHTML=NAV.map(([id,e,t])=>`<button data-nav="${id}" class="${view===id?'active':''}">${e} ${t}</button>`).join('');let v=NAV.find(x=>x[0]===view)||NAV[0];$('#viewKicker').textContent=`LA-99 / ${DISTRICTS.find(x=>x.id===state.district).name.toUpperCase()}`;$('#viewTitle').textContent=v[2].toUpperCase();$('#viewExtra').textContent=`LEVEL ${state.level} • ${fmt(state.cash)} EDDIES`;$('#view').innerHTML=({phone:renderPhone,map:renderMap,jobs:renderJobs,combat:renderCombat,inventory:renderInventory,shop:renderShop,cyber:renderCyber,skills:renderSkills,social:renderSocial,garage:renderGarage,property:renderProperty,craft:renderCraft,factions:renderFactions,casino:renderCasino,journal:renderJournal})[view]();let mission=state.missions.find(m=>m.id===state.activeMission);$('#activeMission').innerHTML=mission?`<b>${esc(m.title)}</b><p>${esc(m.desc)}</p><p class="cyan">${esc(DISTRICTS.find(d=>d.id===mission.district).name)} • ₡${fmt(m.reward)}</p>`:'<p class="muted">No tracked contract. Check your gig board.</p>';$('#feed').innerHTML=state.feed.map(s=>`<p>${esc(s)}</p>`).join('');$('#quick').innerHTML=`<button data-nav="phone">📱 PHONE</button><button data-action="rest">🛌 REST (6H)</button><button data-action="heal">💉 USE MED-STIM (${quantity('med')})</button><button data-action="search">🔍 SCAVENGE</button><button data-action="save">💾 SAVE NOW</button>`;if(view==='map')drawMap();}
function renderMap(){let d=DISTRICTS.find(x=>x.id===state.district);return `<div class="card"><h3>📍 NEARBY / INTERACT</h3><p>Use the district services. Each service opens the appropriate playable interface.</p><div class="actions"><button data-action="interior" data-id="clinic">🦾 Enter Ripperdoc Clinic</button><button data-action="interior" data-id="market">🛒 Enter Market</button><button data-action="interior" data-id="bar">🍸 Enter Neon Bar</button><button data-nav="jobs">📟 Fixer Board</button><button data-action="crime">⚠️ Attack Street Target</button><button data-action="police">🚔 Confront Police</button></div></div><div class="story-box"><div class="eyebrow">WELCOME TO THE SPRAWL</div><h3>${d.emoji} ${d.name}</h3><p>${d.desc} <span class="tag">Recommended Level ${d.level}</span></p><p>Police heat: <b>${state.wanted}/5</b> • Faction control: ${d.faction}</p></div><div class="map-wrap"><canvas id="cityCanvas" width="850" height="405" role="img" aria-label="Interactive district map"></canvas><div class="map-note">👆 Tap a location marker or choose a district below. Travel advances the clock; driving uses your active car.</div></div><div class="cards" style="margin-top:14px">${DISTRICTS.map(p=>`<div class="card"><h3>${p.emoji} ${p.name} ${p.id===state.district?'<span class="pill">HERE</span>':''}</h3><p>${p.desc}</p><small class="muted">Danger LV ${p.level}</small><div class="actions"><button data-action="travel" data-id="${p.id}" ${p.id===state.district?'disabled':''}>🧭 TRAVEL</button><button data-action="explore" data-id="${p.id}" ${p.id!==state.district?'disabled':''}>🔎 EXPLORE</button></div></div>`).join('')}</div>`;}
function drawMap(){let c=$('#cityCanvas');if(!c)return;let ctx=c.getContext('2d'),w=c.width,h=c.height;let g=ctx.createLinearGradient(0,0,w,h);g.addColorStop(0,'#11273b');g.addColorStop(1,'#211d41');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);ctx.lineWidth=1;for(let x=0;x<w;x+=26){ctx.strokeStyle=x%104===0?'#26718a':'#26354d';ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(let y=0;y<h;y+=26){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}let xy=d=>[65+d.x*140,70+d.y*87];ctx.strokeStyle='#d043836b';ctx.lineWidth=7;ctx.beginPath();for(const d of DISTRICTS){let [x,y]=xy(d);ctx.lineTo(x,y)}ctx.stroke();DISTRICTS.forEach(d=>{let [x,y]=xy(d),here=d.id===state.district;ctx.beginPath();ctx.arc(x,y,here?19:14,0,Math.PI*2);ctx.fillStyle=here?'#46e8e4':'#ec699c';ctx.fill();ctx.fillStyle='#0b1521';ctx.font='bold 19px sans-serif';ctx.textAlign='center';ctx.fillText(here?'◆':'●',x,y+6);ctx.font='bold 14px Rajdhani,Arial';ctx.fillStyle='#fff';ctx.fillText(d.name,x,y-25);});c.onclick=e=>{let r=c.getBoundingClientRect(),x=(e.clientX-r.left)*c.width/r.width,y=(e.clientY-r.top)*c.height/r.height;let d=DISTRICTS.find(d=>{let [px,py]=xy(d);return Math.hypot(px-x,py-y)<25});if(d){if(d.id===state.district)explore();else travel(d.id);}};}
function generateMission(type){const t=type||pick(['GIG','BOUNTY','DELIVERY','HEIST','BOSS','CHASE']);let district=pick(DISTRICTS),level=Math.max(1,state.level+R(-1,2)),difficulty=t==='BOSS'?2.1:t==='HEIST'?1.6:t==='BOUNTY'?1.4:1, reward=Math.round((115+level*90)*difficulty+R(20,160));let terms={GIG:['Courier in the Crossfire','Datashard Retrieval','Silent Surveillance'],BOUNTY:['Marked for Removal','The Missing Hitman','Wanted: Dead or Alive'],DELIVERY:['Urgent Medical Drop','Encrypted Package','Smuggler Route'],HEIST:['Bank Vault Breach','Helix Data Raid','Prototype Extraction'],BOSS:['The Iron Butcher','Wraith of the Freeway','Chrome Revenant'],CHASE:['Street Pursuit','Breakaway Driver','Checkpoint Blitz']};return {id:++state.questCounter,type,title:pick(terms[t]),desc:({GIG:'An independent fixer needs muscle and discretion.',BOUNTY:'Track a dangerous target and collect the contract.',DELIVERY:'Transport a package through volatile territory.',HEIST:'Infiltrate a secured site, then fight your way out.',BOSS:'An elite cyber-enhanced warlord controls the area.',CHASE:'Race across the grid while evading hostile units.'})[t],district:district.id,level,reward,status:'available',faction:pick(FACTIONS.slice(0,4))};}
function renderJobs(){let list=state.missions.filter(m=>m.status!=='done');return `<div class="story-box"><h3>📟 FIXER NETWORK / INDEPENDENT CONTRACTS</h3><p>Randomized gigs, bounties, heists, delivery runs, boss hunts and pursuits. Claim a job, travel to its district, then execute.</p><button data-action="refreshJobs">🔄 NEW OFFERS • ₡50</button></div><div class="cards two">${list.map(m=>`<div class="card"><div class="row between"><span class="pill">${m.type}</span><span class="tag">LV ${m.level} • ₡${fmt(m.reward)}</span></div><h3>${esc(m.title)}</h3><p>${esc(m.desc)}</p><p>📍 ${DISTRICTS.find(d=>d.id===m.district).name} • ${m.faction}</p><div class="actions"><button data-action="track" data-id="${m.id}">${state.activeMission===m.id?'✓ TRACKING':'🎯 TRACK'}</button><button class="primary" data-action="mission" data-id="${m.id}">${m.district!==state.district?'🚗 TRAVEL FIRST':'⚔️ EXECUTE'}</button></div></div>`).join('')}</div>`;}
function lockButton(label,enabled,action,reason,where,extra=''){return `<button data-action="${enabled?action:'locked'}" ${enabled?extra:`data-reason="${esc(reason)}" data-go="${where}" class="locked-action"`} title="${enabled?'Ready':esc(reason)}">${enabled?label:'🔒 '+label}</button>${enabled?'':`<small class="requirement">${esc(reason)} · ${esc(where)}</small>`}`;}
function renderCombat(){if(!combat)return `<div class="story-box"><h3>⚔️ COMBAT / TRAINING</h3><p>Train against hostiles, take street fights or complete fixer contracts. Combat uses ammo, stamina, real equipment checks, and a persistent checkpoint on death.</p><button class="primary" data-action="train">⚔️ BEGIN SPARRING</button></div>`;let e=combat.enemy,hasDeck=!!state.cyber.deck,hasSande=!!state.cyber.sande,hasBerserk=!!state.cyber.berserk;return `<div class="story-box"><div class="eyebrow">⚠ ENGAGEMENT // ROUND ${combat.turn}</div><h3>${combat.type==='maxtac'?'☠️ ELITE RESPONSE TEAM':combat.boss?'☠️ BOSS ENCOUNTER':'🎯 HOSTILE CONTACT'}</h3><p>Target armor ${e.armor} · ${combat.type==='police'||combat.type==='maxtac'?'LAW ENFORCEMENT':''}</p></div><div class="combatants"><div class="card combat-enemy"><div class="scene-art">${combat.type==='maxtac'?'🚨':combat.boss?'👹':'🥷'}</div><h3>${esc(e.name)}</h3><p>❤️ ${Math.max(0,e.hp)} / ${e.maxHp}</p><div class="meter"><i class="hp" style="width:${100*e.hp/e.maxHp}%"></i></div><p>🛡️ Armor ${e.armor} • ⚔️ Damage ${e.damage}</p></div><div class="card combat-player"><div class="scene-art">🧍</div><h3>${esc(state.name)}</h3><p>❤️ ${Math.ceil(state.health)} / ${maxHp()} · ⚡ ${Math.ceil(state.energy)} / ${maxEn()}</p><p>🔫 ${item(state.weapon)?.name||'Sidearm'} · 📦 ${state.ammo}/12 loaded · ${state.reserve} reserve</p><p>🧠 RAM ${state.ram}/60 · TRACE ${state.trace}%</p></div></div><div class="card"><div class="combat-text">${esc(combat.message)}</div><div class="actions">${lockButton('🔫 FIRE',state.ammo>0,'attack','Magazine empty: reload or buy ammo','shop')}${lockButton('💥 HEAVY (20⚡)',state.energy>=20&&state.ammo>=2,'heavy','Need 20 stamina and 2 rounds','shop')}${lockButton('🧠 QUICKHACK (25 RAM)',hasDeck&&state.ram>=25&&state.trace<100,'hack',!hasDeck?'Install a Cyberdeck operating system at a Ripperdoc':state.trace>=100?'Security trace at 100%':'Need at least 25 RAM','cyber')}${lockButton('⏱️ SANDEVISTAN (40⚡)',hasSande&&state.energy>=40,'burst',!hasSande?'Install Sandevistan OS at a Ripperdoc':'Need 40 stamina','cyber')}${lockButton('🔥 BERSERK (35⚡)',hasBerserk&&state.energy>=35,'berserk',!hasBerserk?'Install Berserk OS at a Ripperdoc':'Need 35 stamina','cyber')}<button data-action="reload">📦 RELOAD (${state.reserve})</button><button data-action="defend">🛡️ DEFEND</button><button data-action="heal">💉 MED-STIM (${quantity('med')})</button><button data-action="flee">🏃 ESCAPE</button></div></div>`;}

function renderInventory(){return `<div class="story-box"><h3>🎒 BACKPACK / LOADOUT</h3><p>Carry weight: <b>${inventoryWeight()} / ${capacity()} kg</b> • Equipped: ${item(state.weapon)?.name} + ${item(state.armor)?.name}</p></div><div class="cards">${state.inventory.map(i=>{let it=item(i.id);if(!it)return '';return `<div class="card"><h3>${it.emoji} ${it.name} <span class="pill">×${i.qty}</span></h3><p>${it.damage?`Damage ${it.damage} • ${it.rarity}`:it.armor?`Armor ${it.armor}`:`Consumable / material`} • ${it.weight}kg each</p><div class="actions">${WEAPONS.some(w=>w.id===it.id)?`<button data-action="equipWeapon" data-id="${it.id}" ${state.weapon===it.id?'disabled':''}>🔫 EQUIP</button><button data-action="weaponMod" data-id="${it.id}" title="Requires 2 scrap and 1 alloy">🔧 MOD +${state.mods[it.id]||0}/5</button>`:''}${ARMOR.some(w=>w.id===it.id)?`<button data-action="equipArmor" data-id="${it.id}" ${state.armor===it.id?'disabled':''}>🛡️ EQUIP</button>`:''}${['med','battery','ammo','blocker'].includes(it.id)?`<button data-action="consume" data-id="${it.id}">✨ USE</button>`:''}<button data-action="sell" data-id="${it.id}" ${i.id===state.weapon||i.id===state.armor?'disabled':''}>₡ SELL ${Math.floor(it.price*.45)}</button></div></div>`}).join('')}</div>`;}
function renderShop(){let groups=[['weapons','🔫 Weapons',WEAPONS],['armor','🛡️ Armor',ARMOR],['supplies','💊 Supplies',CONSUME]];let arr=groups.find(g=>g[0]===sub)||groups[0];return `<div class="tabs">${groups.map(g=>`<button class="${sub===g[0]?'active':''}" data-action="tab" data-id="${g[0]}">${g[1]}</button>`).join('')}</div><div class="cards">${arr[2].map(it=>`<div class="card"><h3>${it.emoji} ${it.name}</h3><p>${it.damage?'⚔️ '+it.damage+' DMG • '+it.rarity:it.armor?'🛡️ '+it.armor+' armor':'Utility / crafting item'} • ${it.weight}kg</p><p class="gold">₡ ${fmt(it.price)}</p><button data-action="buy" data-id="${it.id}" ${state.cash<it.price?'disabled':''}>🛒 BUY</button></div>`).join('')}</div>`;}
function renderCyber(){const os=['deck','sande','berserk'],zones={deck:'Operating System',sande:'Operating System',berserk:'Operating System',optic:'Eyes',arms:'Arms',hands:'Hands',legs:'Legs',skin:'Integumentary',reflex:'Skeleton',nerves:'Nervous System',blood:'Circulatory'};return `<div class="story-box"><h3>🦾 RIPPERDOC / CHROME INSTALLATION</h3><p>Start fully organic. Chrome is installed by body zone; only ONE operating system may be equipped at a time. Clinic access, credits and street credibility matter.</p><p>🧠 Cyberpsychosis ${state.psy}% · 🛡️ Resistance ${state.psyResist}% · ⭐ Street Cred ${state.streetCred}</p><p class="hint">Unlock route: complete fixer gigs to gain street cred; visit a clinic, buy your operating system and install it.</p><button data-action="buyBlocker">💊 NEURAL STABILIZER ₡240 (-35%)</button><button data-action="useBlocker">💊 USE STABILIZER (${quantity('blocker')})</button></div><div class="cards">${CYBER.map(c=>{let installed=!!state.cyber[c.id],osConflict=os.includes(c.id)&&os.some(k=>k!==c.id&&state.cyber[k]),credReq=c.price>=2500?3:c.price>=1500?1:0,reason=installed?'Installed':osConflict?'Another operating system is equipped':state.streetCred<credReq?`Requires Street Cred ${credReq}; complete fixer jobs`:state.cash<c.price?`Need ₡${fmt(c.price-state.cash)} more`:'';return `<div class="card"><span class="tag">${zones[c.id]||'Body'}</span><h3>${c.emoji} ${c.name}</h3><p>${c.desc}</p><p class="gold">₡${fmt(c.price)} · Cred ${credReq}</p>${lockButton(installed?'✓ INSTALLED':'🦾 INSTALL',!reason,'install',reason,osConflict?'Only one OS (remove your current OS in clinic)':state.streetCred<credReq?'jobs':'shop',`data-id="${c.id}"`)}${osConflict?`<button data-action="removeOS">🔧 Remove current OS</button>`:''}</div>`}).join('')}</div>`;}

function renderSkills(){return `<div class="story-box"><h3>🌟 ATTRIBUTE TREE / NEURAL DISCIPLINE</h3><p>🛡️ Neural Discipline ${state.psyResist}% · Each perk rank costs 1 point and reduces psychosis accumulation by 12 percentage points (up to 60%).</p><button data-action="neuralPerk" ${state.points<1||state.psyResist>=60?'disabled':''}>🧬 TRAIN NEURAL DISCIPLINE (1 POINT)</button><p>Available points: <b class="cyan">${state.points}</b>. Level up through combat, missions, races and exploration. Costs 1 point per attribute.</p></div><div class="cards">${statNames.map(id=>`<div class="card"><h3>${{body:'💪',reflexes:'⚡',tech:'🔧',intelligence:'🧠',cool:'😎'}[id]} ${cap(id)}</h3><p>Level <b>${state.stats[id]}</b> / 20</p><p>${{body:'Maximum health, carry capacity and melee.',reflexes:'Attack strength, quick strikes, racing.',tech:'Crafting and engineering.',intelligence:'Hacking damage, security systems.',cool:'Critical hits, charisma and stealth.'}[id]}</p><button data-action="stat" data-id="${id}" ${state.points<1||state.stats[id]>=20?'disabled':''}>⬆ UPGRADE (+1)</button></div>`).join('')}</div>`;}
function renderPhone(){return `<div class="story-box"><h3>📱 AGENT PHONE / QUICK ACCESS</h3><p>All important systems in one place. Locked actions always explain what you need and where to get it.</p></div><div class="cards two">${[['map','🗺️ Explore Districts','Locations and buildings'],['jobs','📟 Fixer Contracts','Earn money and street cred'],['cyber','🦾 Ripperdoc','Buy/install chrome'],['shop','🛒 Black Market','Buy ammo and supplies'],['social','❤️ Contacts','Talk, date and recruit'],['garage','🏎️ Motorpool','Race and maintain vehicles'],['skills','🌟 Perks','Resist cyberpsychosis'],['journal','📖 Dossier','Save, export, history']].map(([id,name,desc])=>`<button class="phone-tile" data-nav="${id}"><b>${name}</b><small>${desc}</small></button>`).join('')}</div>`;}
function renderSocial(){return `<div class="story-box"><h3>❤️ CONTACTS / COMPANIONS</h3><p>Build trust, take people on dates, make friends or start romances. Dishonest choices may provoke betrayal. Companions help in combat.</p></div><div class="cards two">${NPCS.map(n=>{let rel=state.relationships[n.id];return `<div class="card"><div class="scene-art">${n.emoji}</div><div class="row between"><h3>${n.name}</h3><span class="pill">${rel.status}</span></div><p>${n.role} • ${DISTRICTS.find(d=>d.id===n.district).name}</p><p>💕 Affection ${rel.affection} • 🤝 Trust ${rel.trust}</p><p class="hint">${pick(n.lines)}</p><div class="actions"><button data-action="talk" data-id="${n.id}">💬 TALK</button><button data-action="gift" data-id="${n.id}">🎁 GIFT ₡100</button><button data-action="date" data-id="${n.id}" ${rel.affection<20?'disabled':''}>❤️ DATE ₡150</button><button data-action="companion" data-id="${n.id}" ${rel.trust<35?'disabled':''}>${rel.companion?'👤 DISMISS':'🤝 RECRUIT'}</button></div></div>`}).join('')}</div>`;}
function renderGarage(){return `<div class="story-box"><h3>🏎️ MOTORPOOL / UNDERGROUND RACING</h3><p>Acquire vehicles, tune engines and win illegal races. Pursuits increase police attention.</p><button data-action="race" ${!state.activeCar?'disabled':''}>🏁 ENTER STREET RACE • ₡100</button></div><div class="cards">${CARS.map(c=>{let own=state.cars.includes(c.id);return `<div class="card"><div class="scene-art">${c.emoji}</div><h3>${c.name}</h3><p>⚡ Speed ${c.speed} • 🛞 Grip ${c.grip} • Upgrade +${state.upgrades[c.id]||0}</p><p class="gold">₡ ${fmt(c.price)}</p><div class="actions">${!own?`<button data-action="carBuy" data-id="${c.id}" ${state.cash<c.price?'disabled':''}>🛒 BUY</button>`:`<button data-action="carEquip" data-id="${c.id}" ${state.activeCar===c.id?'disabled':''}>${state.activeCar===c.id?'✓ ACTIVE':'🚗 DRIVE'}</button><button data-action="carUpgrade" data-id="${c.id}">🔧 TUNE ₡${500+(state.upgrades[c.id]||0)*400}</button>`}</div></div>`}).join('')}</div>`;}
function renderProperty(){return `<div class="story-box"><h3>🏡 REAL ESTATE & PASSIVE INCOME</h3><p>Own multiple safehouses. Rest to restore health and lower heat. Businesses produce credits every in-game day.</p></div><h3>🏠 Residences</h3><div class="cards">${HOMES.map(h=>`<div class="card"><h3>${h.emoji} ${h.name}</h3><p>Recovery: +${h.regen===999?'Full':h.regen} HP per rest</p><p class="gold">₡${fmt(h.price)}</p><button data-action="homeBuy" data-id="${h.id}" ${state.homes.includes(h.id)||state.cash<h.price?'disabled':''}>${state.homes.includes(h.id)?'✓ OWNED':'🏠 PURCHASE'}</button></div>`).join('')}</div><h3>💼 Businesses</h3><div class="cards">${BUSINESSES.map(b=>`<div class="card"><h3>${b.emoji} ${b.name}</h3><p>Daily income: <b class="cyan">₡${fmt(b.income)}</b></p><p class="gold">₡${fmt(b.price)}</p><button data-action="bizBuy" data-id="${b.id}" ${state.businesses.includes(b.id)||state.cash<b.price?'disabled':''}>${state.businesses.includes(b.id)?'✓ OWNED':'💼 INVEST'}</button></div>`).join('')}</div>`;}
const RECIPES=[{name:'Med-Stim',emoji:'💉',output:'med',amount:2,req:[['scrap',2],['alloy',1]],tech:3},{name:'Focus Cell',emoji:'🔋',output:'battery',amount:2,req:[['scrap',3]],tech:3},{name:'Alloy Bundle',emoji:'⚙️',output:'alloy',amount:2,req:[['scrap',5]],tech:5}];
function renderCraft(){return `<div class="story-box"><h3>🛠️ FABRICATION BENCH</h3><p>Salvage materials from contracts or scavenge. Higher Tech unlocks advanced fabrication.</p></div><div class="cards">${RECIPES.map((r,i)=>`<div class="card"><h3>${r.emoji} ${r.name} ×${r.amount}</h3><p>Requires Tech ${r.tech}</p><p>${r.req.map(([id,n])=>`${item(id).emoji} ${item(id).name} ${quantity(id)}/${n}`).join(' • ')}</p><button data-action="craft" data-id="${i}" ${state.stats.tech<r.tech||!r.req.every(([id,n])=>quantity(id)>=n)?'disabled':''}>⚙️ FABRICATE</button></div>`).join('')}</div>`;}
function renderFactions(){return `<div class="story-box"><h3>🏴 FACTION RELATIONS</h3><p>Your actions influence security, alliances and contract opportunities. Earn or lose standing through jobs and street encounters.</p></div><div class="cards">${FACTIONS.map((f,i)=>{let r=state.reputation[f]||0;return `<div class="card"><h3>${['🐍','🏢','🏜️','🕶️','🚔'][i]} ${f}</h3><p>Reputation: <b class="${r<0?'pink':'cyan'}">${r>0?'+':''}${r}</b></p><p>${r>50?'ALLIED':r>15?'FRIENDLY':r<-50?'HOSTILE':r<-15?'UNTRUSTED':'NEUTRAL'}</p><div class="meter"><i style="width:${(r+100)/2}%;background:var(--cyan)"></i></div></div>`}).join('')}</div>`;}
function renderCasino(){return `<div class="story-box"><h3>🎰 PHANTOM ARCADE</h3><p>Risk credits on slots or a street coin flip. All outcomes use random chance, with no real-money gambling.</p></div><div class="cards two"><div class="card"><h3>🎰 Neon Slots</h3><p>Entry ₡50 • Triple icons: ₡400 • Double icons: ₡120</p><button class="primary" data-action="slotsGame">🎰 SPIN ₡50</button></div><div class="card"><h3>🪙 Chrome Coin</h3><p>Stake ₡100. A correct call returns ₡200.</p><div class="actions"><button data-action="coin" data-id="heads">👑 HEADS</button><button data-action="coin" data-id="tails">💀 TAILS</button></div></div></div>`;}
function renderJournal(){return `<div class="story-box"><h3>📖 MERCENARY DOSSIER</h3><p>${esc(state.name)} • ${state.gender} • ${state.origin} • Level ${state.level} • Completed contracts ${state.completed} • Kills ${state.kills} • Defeats ${state.defeats}</p><div class="actions"><button data-action="export" data-slot="${state.slot}">🔒 ENCRYPTED EXPORT</button><button data-action="slots">▤ MANAGE SLOTS</button><button data-action="settings">⚙ SETTINGS</button></div></div><div class="card"><h3>📡 ACTIVITY LOG</h3>${state.log.slice(0,35).map(x=>`<p class="hint">${esc(x)}</p>`).join('')}</div>`;}
function travel(id){if(combat)return notify('Finish combat before travelling.');let d=DISTRICTS.find(x=>x.id===id);if(!d||d.id===state.district)return;let h=state.activeCar?1:3;state.district=d.id;tick(h);addFeed(`🚗 Traveled to ${d.name} (${h}h).`);if(state.wanted>=3&&Math.random()<.45)startFight('police',null);else if(d.level>state.level+2&&Math.random()<.2)startFight('ambush',null);saveRender();}
function explore(){tick(1);const roll=Math.random();if(roll<.28){let amt=R(40,150)+state.level*9;state.cash+=amt;addFeed(`💰 Found ₡${amt} in forgotten containers.`);}else if(roll<.55){let id=pick(['scrap','scrap','alloy','med','battery']);if(gainItem(id))addFeed(`🔎 Scavenged ${item(id).name}.`);}else if(roll<.78){addFeed('⚔️ Hostile movement detected!');startFight('ambush',null);}else{let xp=R(15,40);xpGain(xp);addFeed(`🌆 Scouted the area and learned the streets (+${xp} XP).`);}state.heat=Math.max(0,state.heat-1);saveRender();}
function search(){if(combat)return;tick(1);let outcomes=['scrap','scrap','med','alloy','battery'];let id=pick(outcomes);if(gainItem(id))addFeed(`🔍 Scavenge success: ${item(id).name}.`);if(Math.random()<.2)startFight('ambush',null);saveRender();}
function rest(){if(combat)return notify('Not during combat.');tick(6);let house=state.homes.map(id=>HOMES.find(x=>x.id===id)).sort((a,b)=>b.regen-a.regen)[0];state.health=Math.min(maxHp(),state.health+(house?house.regen:35));state.energy=maxEn();state.psy=Math.max(0,state.psy-25);state.wanted=Math.max(0,state.wanted-1);addFeed(`🛌 Recovered at ${house?.name||'a rented capsule'}.`);saveRender();}
function useConsumable(id){if(quantity(id)<1)return notify('Out of supplies.');if(id==='blocker'){removeItem(id);state.psy=Math.max(0,state.psy-35);notify('💊 Neural strain reduced 35%.');}else if(id==='ammo'){removeItem(id);state.reserve+=24;notify('📦 +24 rounds to reserve.');}else if(id==='med'){if(state.health>=maxHp())return notify('Your health is already full.');removeItem(id);state.health=Math.min(maxHp(),state.health+55+state.stats.tech*2);notify('❤️ Health restored.');}else if(id==='battery'){if(state.energy>=maxEn())return notify('Focus is already full.');removeItem(id);state.energy=Math.min(maxEn(),state.energy+55);notify('⚡ Focus restored.');}if(combat){combat.message=`${state.name} used ${item(id).name}.`;enemyTurn();}saveRender();}
function startFight(type,mission){let level=mission?.level||Math.max(1,state.level+R(-1,1));let boss=type==='boss'||type==='maxtac'||mission?.type==='BOSS';let names=type==='maxtac'?['MAX-TAC Rapid Response','MAX-TAC Psycho Squad']:boss?['The Iron Butcher','Chrome Revenant','Wraith Commander']:type==='police'?['LA-99 Tactical Officer','LA-99 Enforcer']:['Back-Alley Scav','Chrome Raider','Rogue Netrunner','Contract Killer'];let max=Math.round((55+level*28)*(type==='maxtac'?4.5:boss?2.5:1));combat={type,missionId:mission?.id||null,boss,turn:1,guard:false,enemy:{name:mission?.type==='BOSS'?mission.title:pick(names),hp:max,maxHp:max,damage:Math.round((8+level*4)*(type==='maxtac'?2.8:boss?1.6:1)),armor:level*2+(type==='maxtac'?20:boss?8:0)},message:'Hostile target acquired. Choose your action.'};view='combat';notify('⚠️ COMBAT ENGAGED');render();}
function damageEnemy(dmg,crit=false){combat.enemy.hp=Math.max(0,combat.enemy.hp-dmg);combat.message=`${crit?'💥 CRITICAL! ':'🎯 '}You dealt ${dmg} damage to ${combat.enemy.name}.`;if(combat.enemy.hp<=0){winFight();return true;}return false;}
function attack(kind){if(!combat)return;let weapon=item(state.weapon)||WEAPONS[0],base=weapon.damage+(state.mods[state.weapon]||0)*7+state.stats.reflexes*2+state.level*2;let cost=0;if(kind==='heavy'){cost=20;base*=1.65;}if(kind==='hack'){if(!state.cyber.deck)return locked('A Cyberdeck is required for Quickhacking.','cyber');if(state.ram<25||state.trace>=100)return locked('Insufficient RAM or security trace maxed.','cyber');state.ram-=25;state.trace=Math.min(100,state.trace+R(12,25));cost=0;base=18+state.stats.intelligence*8+state.level*3;}if(kind==='burst'){if(!state.cyber.sande)return locked('Sandevistan operating system required.','cyber');cost=40;base*=2.4;state.psy+=Math.max(2,18-state.psyResist*.22);}
if(kind==='berserk'){if(!state.cyber.berserk)return locked('Berserk operating system required.','cyber');cost=35;base*=2.1;state.psy+=Math.max(2,14-state.psyResist*.2);}
if(['attack','heavy','burst'].includes(kind)){let rounds=kind==='heavy'?2:1;if(state.ammo<rounds)return locked('Magazine empty. Reload using reserve ammunition.','shop');state.ammo-=rounds;}if(kind==='defend'){combat.guard=true;state.energy=Math.min(maxEn(),state.energy+18);combat.message='🛡️ Braced for the next attack. Focus recovered.';enemyTurn();return;}if(state.energy<cost)return notify('Not enough focus.');state.energy-=cost;let crit=Math.random()<.07+state.stats.cool*.02,dmg=Math.max(1,Math.round(base*R(85,115)/100*(crit?1.75:1)-combat.enemy.armor));let companion=NPCS.find(n=>state.relationships[n.id].companion);if(companion){let aid=R(4,10)+Math.floor(state.relationships[companion.id].trust/10);dmg+=aid;}let done=damageEnemy(dmg,crit);if(!done){if(state.psy>=100){triggerPsychosis();return;}enemyTurn();}saveRender();}
function enemyTurn(){if(!combat)return;let e=combat.enemy;let evade=Math.min(.38,state.stats.reflexes*.015);let dmg=Math.max(1,Math.round(e.damage*R(70,130)/100-armorValue()*(combat.guard?1.9:.45)));if(Math.random()<evade)dmg=0;state.health=Math.max(0,state.health-dmg);combat.message+=dmg?` | ${e.name} hits you for ${dmg}.`:` | You dodged the attack!`;combat.guard=false;combat.turn++;state.energy=Math.min(maxEn(),state.energy+8);if(state.health<=0)loseFight();}
function winFight(){let m=state.missions.find(m=>m.id===combat.missionId);let xp=R(25,55)+state.level*22+(combat.boss?130:0),cash=R(35,130)+(combat.boss?400:0);state.kills++;if(m){cash+=m.reward;xp+=Math.round(m.reward*.23);state.completed++;state.streetCred+=m.type==='BOSS'?3:1;reputation(m.faction,R(5,11));state.missions=state.missions.filter(x=>x.id!==m.id);if(state.activeMission===m.id)state.activeMission=null;state.missions.push(generateMission());if(['BOUNTY','HEIST'].includes(m.type))state.wanted=Math.min(5,state.wanted+1);}state.cash+=cash;xpGain(xp);if(Math.random()<.65)gainItem(pick(['scrap','med','alloy']));addFeed(`🏆 Victory! ₡${fmt(cash)} and ${xp} XP earned.`);combat=null;view='jobs';policeResponse();notify(`🏆 VICTORY +₡${fmt(cash)} +${xp} XP`);}
function loseFight(){deathRestored=true;let defeats=state.defeats+1;let s=readSlot(state.slot);combat=null;if(s){state=s;upgradeState();state.defeats=defeats;state.health=Math.max(1,state.health);view='map';modal(`<h2>☠ FLATLINED</h2><p>Your neural signal vanished. Your last saved snapshot has been restored.</p><button class="primary" data-action="close">↺ RELOAD SAVE</button>`);}else{state.health=maxHp();view='map';notify('Restored from emergency checkpoint.');} }
function flee(){if(!combat)return;if(Math.random()<.55+state.stats.reflexes*.015){addFeed('🏃 Escaped hostile contact.');combat=null;state.wanted=Math.min(5,state.wanted+1);view='map';}else{combat.message='Escape route blocked!';enemyTurn();}saveRender();}
function doMission(id){let m=state.missions.find(x=>x.id===Number(id));if(!m)return;if(m.district!==state.district)return travel(m.district);state.activeMission=m.id;tick(1);if(['DELIVERY','CHASE'].includes(m.type)){let power=state.stats.reflexes+state.stats.cool+(state.activeCar?CARS.find(c=>c.id===state.activeCar).speed+(state.upgrades[state.activeCar]||0)*2:0),threshold=m.level*2+R(3,12);if(power>=threshold){state.cash+=m.reward;xpGain(m.reward/4|0);reputation(m.faction,5);state.completed++;state.missions=state.missions.filter(x=>x.id!==m.id);state.missions.push(generateMission());state.activeMission=null;addFeed(`✅ ${m.title} complete! ₡${fmt(m.reward)} earned.`);if(m.type==='CHASE')state.wanted=Math.min(5,state.wanted+1);}else{addFeed(`⚠ ${m.title} turned into a hostile encounter.`);startFight('ambush',m);}}else startFight(m.type==='BOSS'?'boss':'mission',m);saveRender();}
function buyItem(id){let it=item(id);if(!it||state.cash<it.price)return;let done=gainItem(id);if(done){state.cash-=it.price;notify(`🛒 Purchased ${it.name}.`);}saveRender();}
function sellItem(id){let it=item(id);if(!it||state.weapon===id||state.armor===id)return;if(removeItem(id)){state.cash+=Math.floor(it.price*.45);notify(`₡ Sold ${it.name}.`);}saveRender();}

function locked(reason,go='phone'){notify('🔒 '+reason);modal(`<h2>🔒 ACTION LOCKED</h2><p>${esc(reason)}</p><p class="hint">Suggested route: ${esc(go.toUpperCase())}</p><div class="actions"><button data-nav="${go}">📍 GO TO ${esc(go.toUpperCase())}</button><button data-action="close">CLOSE</button></div>`);}
function policeResponse(){if(!state||combat)return;if(state.wanted>=5){if(Math.random()<.42){addFeed('🚨 MAX-TAC deployed: high-risk threat intercepted.');startFight('maxtac',null);}else addFeed('🚨 MAX-TAC dispatch on standby. Tactical drones searching.');}else if(state.wanted>=3&&Math.random()<.3)startFight('police',null);}
function triggerPsychosis(){state.psy=100;let victims=R(2,8),officers=R(1,4);state.wanted=5;state.trauma+=1;addFeed(`☠️ CYBERPSYCHOSIS: uncontrolled rampage. ${victims} civilian NPCs and ${officers} police officers killed.`);document.body.classList.add('psychosis');combat=null;view='map';render();modal(`<h2>☠️ NEURAL COLLAPSE</h2><p>Your implants overrode motor control. In a blackout, your character attacked ${victims} civilian NPCs and ${officers} police officers. Elite response units arrived.</p><p>🚨 MAX-TAC TERMINATION CONFIRMED · NEURAL SIGNAL LOST</p><button data-action="psyDeath">☠️ FLATLINED — RELOAD CHECKPOINT</button>`);}

function action(a,id,btn){if(!state&& !['new','continue','slots','import','help','create','load','delete','close','settings','export','backMenu'].includes(a))return;switch(a){case 'new':characterModal();break;case 'continue':continueGame();break;case 'slots':slotModal();break;case 'create':{let name=$('#newName').value.trim().slice(0,24)||'Merc',gender=$('#newGender').value,origin=$('#newOrigin').value,slot=Number($('#newSlot').value);if(readSlot(slot)&&!confirm('Overwrite the existing save in slot '+(slot+1)+'?'))break;startGame(fresh(name,gender,origin,slot));break;}case 'load':{let s=readSlot(Number(btn.dataset.slot));if(s)startGame(s);break;}case 'delete':{let i=Number(btn.dataset.slot);if(confirm('Permanently delete save slot '+(i+1)+'?')){localStorage.removeItem('nr2099-slot-'+i);slotModal();}break;}case 'save':if(combat)return notify('⚠ Cannot save during an active encounter.');persist();notify('💾 Progress saved!');break;case 'export':exportSave(Number(btn.dataset.slot));break;case 'import':$('#importFile').click();break;case 'settings':modal(`<h2>⚙ GAME SETTINGS</h2><p class="hint">Sounds are off by default. The game runs without external assets; the optional web font needs internet.</p><button data-action="sound">${settings.sound?'🔊 SOUND ON — TAP TO MUTE':'🔇 SOUND OFF — TAP TO ENABLE'}</button><div class="actions"><button data-action="save">💾 SAVE</button><button data-action="slots">▤ SAVE SLOTS</button><button data-action="backMenu">↩ TITLE SCREEN</button></div>`);break;case 'sound':settings.sound=!settings.sound;localStorage.setItem('nr2099-settings',JSON.stringify(settings));action('settings');break;case 'backMenu':if(state)persist();closeModal();showMenu();break;case 'close':closeModal();break;case 'help':modal(`<h2>📖 HOW TO PLAY</h2><p>1. Create a merc and choose one of three local save slots.</p><p>2. Explore the city map, scavenge, buy gear and accept fixer contracts.</p><p>3. Travel to your target district, complete randomized gigs and win tactical battles.</p><p>4. Spend attribute points, install cyberware, collect vehicles, build friendships and own businesses.</p><p>5. Autosave occurs after gameplay actions. Export encrypted archives to keep a password-protected backup.</p><p class="hint">Tip: Keep Med-Stims stocked. Cyberpsychosis can cause neural overload in combat. Police heat decreases as days pass or when resting.</p>`);break;
case 'locked':locked(btn.dataset.reason,btn.dataset.go||'phone');break;case 'psyDeath':document.body.classList.remove('psychosis');closeModal();loseFight();render();break;case 'reload':{if(!combat)return;let n=Math.min(12-state.ammo,state.reserve);if(n<=0)return locked('No reserve ammo. Buy Ballistic Ammo Packs in Market.','shop');state.ammo+=n;state.reserve-=n;combat.message=`📦 Reloaded ${n} rounds.`;enemyTurn();saveRender();break;}case 'buyBlocker':{if(state.cash<240)return locked('You need ₡240 for a Neural Stabilizer.','shop');state.cash-=240;gainItem('blocker');saveRender();break;}case 'useBlocker':{if(!quantity('blocker'))return locked('Buy Neural Stabilizers at a Ripperdoc.','cyber');removeItem('blocker');state.psy=Math.max(0,state.psy-35);addFeed('💊 Neural stabilizer suppressed psychosis by 35%.');saveRender();break;}case 'removeOS':{let c=CYBER.find(v=>['deck','sande','berserk'].includes(v.id)&&state.cyber[v.id]);if(!c)return;delete state.cyber[c.id];state.stats[c.stat]-=c.bonus;addFeed(`🔧 Uninstalled ${c.name}.`);saveRender();break;}case 'neuralPerk':{if(state.points<1||state.psyResist>=60)return;state.points--;state.psyResist+=12;addFeed('🧬 Neural Discipline trained: +12% resilience.');saveRender();break;}case 'interior':{let areas={clinic:['🦾 Underground Ripperdoc','Surgical bays glow cyan. A ripperdoc offers implant installation.','cyber'],market:['🛒 Night Market','A maze of weapon racks and supply counters.','shop'],bar:['🍸 The Afterglow','Fixers and off-duty mercs trade rumors over synth cocktails.','social']},v=areas[id];if(!v)return;modal(`<h2>${v[0]}</h2><p>${v[1]}</p><div class="actions"><button data-nav="${v[2]}">🚪 INTERACT / ENTER</button><button data-action="close">↩ EXIT</button></div>`);break;}case 'crime':{state.wanted=Math.min(5,state.wanted+R(1,2));state.kills++;reputation('LA-99 Police',-12);addFeed('🚨 Violent street assault reported by witnesses. Police heat increased.');policeResponse();if(!combat)startFight('ambush',null);saveRender();break;}case 'police':{state.wanted=Math.min(5,state.wanted+1);startFight('police',null);render();break;}case 'travel':travel(id);break;case 'explore':explore();break;case 'search':search();break;case 'rest':rest();break;case 'heal':if(combat&&quantity('med')&&state.health<maxHp())useConsumable('med');else useConsumable('med');break;case 'train':startFight('training');break;case 'attack':case 'heavy':case 'hack':case 'burst':case 'defend':attack(a);break;case 'flee':flee();break;
case 'refreshJobs':if(state.cash<50)return notify('₡50 required.');state.cash-=50;state.missions=state.missions.filter(m=>m.id===state.activeMission);while(state.missions.length<4)state.missions.push(generateMission());saveRender();break;case 'track':state.activeMission=Number(id);saveRender();break;case 'mission':doMission(id);break;
case 'tab':sub=id;render();break;case 'buy':buyItem(id);break;case 'sell':sellItem(id);break;case 'consume':useConsumable(id);break;case 'equipWeapon':if(quantity(id)){state.weapon=id;saveRender();}break;case 'equipArmor':if(quantity(id)){state.armor=id;saveRender();}break;case 'weaponMod':{let lv=state.mods[id]||0;if(lv>=5)return notify('Weapon modification maxed out.');if(quantity('scrap')<2||quantity('alloy')<1)return notify('Mod requires 2 scrap + 1 alloy.');removeItem('scrap',2);removeItem('alloy',1);state.mods[id]=lv+1;addFeed(`🔧 Upgraded ${item(id).name} to mod tier ${lv+1}.`);saveRender();break;}
case 'install':{let c=CYBER.find(x=>x.id===id);if(!c||state.cyber[id])return;let credReq=c.price>=2500?3:c.price>=1500?1:0;if(state.streetCred<credReq)return locked(`Requires Street Cred ${credReq}; complete fixer gigs.`,'jobs');if(state.cash<c.price)return locked(`Need ₡${fmt(c.price-state.cash)} more.`,'jobs');if(['deck','sande','berserk'].includes(id)&&['deck','sande','berserk'].some(k=>k!==id&&state.cyber[k]))return locked('Only one operating system can be installed; remove your current OS.','cyber');state.cash-=c.price;state.cyber[id]=true;state.stats[c.stat]+=c.bonus;state.psy=Math.min(100,state.psy+Math.max(2,12-state.psyResist*.15));if(state.psy>=100){triggerPsychosis();break;}addFeed(`🦾 Installed ${c.name}. Neural strain elevated.`);saveRender();break;}case 'stat':if(state.points&&state.stats[id]<20){state.points--;state.stats[id]++;saveRender();}break;
case 'talk':{let n=NPCS.find(x=>x.id===id),r=state.relationships[id],good=Math.random()<.78;r.trust=Math.max(0,Math.min(100,r.trust+(good?R(4,9):-R(1,5))));r.affection=Math.max(0,Math.min(100,r.affection+(good?R(2,6):-2)));r.status=r.affection>=65&&r.dates>=2?'Partner':r.trust>=55?'Close Friend':r.trust>=20?'Friend':'Acquaintance';if(!good&&r.trust<12&&r.affection>15&&Math.random()<.15){r.status='Betrayed';state.wanted=Math.min(5,state.wanted+1);addFeed(`💔 ${n.name} leaked your location.`);}tick(1);modal(`<h2>${n.emoji} ${n.name}</h2><p>“${esc(pick(n.lines))}”</p><p class="cyan">${good?'A good conversation. You seem closer.':'An awkward exchange. Trust wavers.'}</p><button data-action="close">CONTINUE</button>`);persist();break;}case 'gift':{let r=state.relationships[id];if(state.cash<100)return notify('Not enough credits.');state.cash-=100;r.affection=Math.min(100,r.affection+12);r.trust=Math.min(100,r.trust+4);tick(1);saveRender();break;}case 'date':{let r=state.relationships[id];if(state.cash<150)return notify('Not enough credits.');state.cash-=150;r.dates++;r.affection=Math.min(100,r.affection+R(9,17));r.trust=Math.min(100,r.trust+R(4,10));r.status=r.affection>=65&&r.dates>=2?'Partner':'Dating';tick(3);addFeed(`❤️ Went on a date with ${NPCS.find(n=>n.id===id).name}.`);saveRender();break;}case 'companion':{let r=state.relationships[id];if(!r.companion)for(const v of Object.values(state.relationships))v.companion=false;r.companion=!r.companion;saveRender();break;}
case 'carBuy':{let c=CARS.find(x=>x.id===id);if(state.cash<c.price)return;state.cash-=c.price;state.cars.push(id);state.activeCar=id;saveRender();break;}case 'carEquip':state.activeCar=id;saveRender();break;case 'carUpgrade':{let lv=state.upgrades[id]||0,cost=500+lv*400;if(lv>=5)return notify('Maximum tune reached.');if(state.cash<cost)return notify('Not enough credits.');state.cash-=cost;state.upgrades[id]=lv+1;saveRender();break;}case 'race':{if(!state.activeCar||state.cash<100)return notify('Need a vehicle and ₡100.');state.cash-=100;tick(2);let c=CARS.find(x=>x.id===state.activeCar),score=c.speed+(state.upgrades[c.id]||0)*2+state.stats.reflexes+R(0,12),target=R(12,22);if(score>=target){let prize=R(250,650);state.cash+=prize;xpGain(75);notify(`🏁 RACE WON! ₡${prize}`);addFeed(`🏎️ Street race win at ${DISTRICTS.find(d=>d.id===state.district).name}.`);}else{state.wanted=Math.min(5,state.wanted+1);notify('🏁 Race lost! Police attention increased.');}saveRender();break;}
case 'homeBuy':{let h=HOMES.find(x=>x.id===id);if(state.cash<h.price)return;state.cash-=h.price;state.homes.push(id);saveRender();break;}case 'bizBuy':{let b=BUSINESSES.find(x=>x.id===id);if(state.cash<b.price)return;state.cash-=b.price;state.businesses.push(id);saveRender();break;}case 'craft':{let r=RECIPES[Number(id)];if(!r||state.stats.tech<r.tech||!r.req.every(([k,n])=>quantity(k)>=n))return;let freed=r.req.reduce((t,[k,n])=>t+(item(k)?.weight||0)*n,0);if(inventoryWeight()-freed+item(r.output).weight*r.amount>capacity())return notify('Too heavy to craft.');r.req.forEach(([k,n])=>removeItem(k,n));gainItem(r.output,r.amount);xpGain(10);saveRender();break;}
case 'slotsGame':{if(state.cash<50)return notify('Not enough credits.');state.cash-=50;let icons=['💎','🍒','⚡','🔔','7️⃣'],values=[pick(icons),pick(icons),pick(icons)],reward=values.every(v=>v===values[0])?400:new Set(values).size===2?120:0;state.cash+=reward;modal(`<h2>🎰 PHANTOM SLOTS</h2><div class="scene-art">${values.join(' ')}</div><h3>${reward?`WIN +₡${reward}`:'NO MATCH'}</h3><button data-action="close">CONTINUE</button>`);persist();break;}case 'coin':{if(state.cash<100)return notify('Not enough credits.');state.cash-=100;let result=Math.random()<.5?'heads':'tails',win=result===id;if(win)state.cash+=200;modal(`<h2>🪙 CHROME COIN</h2><div class="scene-art">${result==='heads'?'👑':'💀'}</div><h3>${win?'YOU WIN +₡100':'YOU LOSE ₡100'}</h3><p>The coin landed ${result.toUpperCase()}.</p><button data-action="close">CONTINUE</button>`);persist();break;}
}}
// Password-based authenticated encryption: PBKDF2-SHA-256, AES-256-GCM, random 16-byte salt + 12-byte IV.
// This protects portable archives from casual inspection/tampering without password; browser-local game data remains editable.
function b64(bytes){let s='';for(const b of bytes)s+=String.fromCharCode(b);return btoa(s);}function unb64(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0));}
async function derive(password,salt){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:210000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
async function exportSave(slot){let obj=readSlot(slot);if(!obj)return notify('No save exists in that slot.');if(!crypto.subtle)return notify('Encryption requires localhost or HTTPS.');let password=prompt('🔒 Set an encryption password for your exported save (at least 8 characters). KEEP IT SAFE: there is no recovery.');if(password===null)return;if(password.length<8)return notify('Password must be at least 8 characters.');try{let salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await derive(password,salt),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(JSON.stringify(obj)));let file={format:'NR2099-ENCRYPTED-V1',kdf:'PBKDF2-SHA256',iterations:210000,alg:'AES-256-GCM',salt:b64(salt),iv:b64(iv),payload:b64(new Uint8Array(cipher))};let blob=new Blob([JSON.stringify(file)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`neon-requiem-slot-${slot+1}.nr2099`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('🔒 Encrypted save exported.');}catch(e){notify('Encryption failed: '+e.message);}}
async function importSave(file){if(!file)return;if(!crypto.subtle)return notify('Import requires HTTPS or localhost.');if(file.size>2_000_000)return notify('Save file too large.');try{let obj=JSON.parse(await file.text());if(obj.format!=='NR2099-ENCRYPTED-V1'||obj.alg!=='AES-256-GCM'||obj.iterations!==210000)throw Error('Unrecognized encrypted archive');let password=prompt('🔑 Enter the password used to encrypt this save.');if(password===null)return;let key=await derive(password,unb64(obj.salt)),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(obj.iv)},key,unb64(obj.payload)),s=JSON.parse(new TextDecoder().decode(plain));if(!validateSave(s))throw Error('Save validation failed');let slot=Number(prompt('Import into which local slot? Enter 1, 2, or 3. Existing data will be overwritten.','1'))-1;if(![0,1,2].includes(slot))return notify('Import canceled: invalid slot.');if(readSlot(slot)&&!confirm('Overwrite slot '+(slot+1)+'?'))return;s.slot=slot;localStorage.setItem('nr2099-slot-'+slot,JSON.stringify(s));localStorage.setItem('nr2099-last',String(slot));notify('🔓 Save imported.');slotModal();}catch(e){notify('Import failed: incorrect password, corrupt file or invalid save.');}finally{$('#importFile').value='';}}
window.addEventListener('DOMContentLoaded',()=>{try{settings={...settings,...JSON.parse(localStorage.getItem('nr2099-settings')||'{}')};}catch{}document.addEventListener('click',e=>{let nav=e.target.closest('[data-nav]');if(nav){closeModal();return navTo(nav.dataset.nav);}let target=e.target.closest('[data-action]');if(target)action(target.dataset.action,target.dataset.id,target);});$('#homeBtn').onclick=()=>{if(state)persist();showMenu();};$('#closeModal').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal();});$('#importFile').onchange=e=>importSave(e.target.files?.[0]);window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal').classList.contains('hidden'))closeModal();});boot();});
